#!/usr/bin/env python3
# Piece 4-B - non-money List writes go free-form through Kriya via /binders/*.
# Repoints 11 write/detail fns + widens binderToLead (phone) + adds write helpers.
# Anchored + idempotent. Invoice/payment money is 4-C (the witnessed money door).
import base64, sys, os
PATH = "lib/vendor/api/vendor.ts"
def d(s): return base64.b64decode(s).decode("utf-8")
EDITS = [
    ("binderToLead", "", ""),
    ("binderToExpense", "", ""),
    ("patchLeadState", "", ""),
    ("fetchClientDetail", "", ""),
    ("createLead", "", ""),
    ("updateLead", "", ""),
    ("fetchLeadDetail", "", ""),
    ("createClient", "", ""),
    ("updateClient", "", ""),
    ("deleteClient", "", ""),
    ("createExpense", "", ""),
    ("updateExpense", "", ""),
    ("deleteExpense", "", "")
]
if not os.path.exists(PATH):
    print("FATAL: %s not found (run from dreamos-pwa root)." % PATH); sys.exit(1)
text = open(PATH, encoding="utf-8").read()
applied = skipped = 0
for label, o_b64, n_b64 in EDITS:
    old, new = d(o_b64), d(n_b64)
    if new in text:
        print("SKIP  [%s] already applied." % label); skipped += 1; continue
    c = text.count(old)
    if c == 1: text = text.replace(old, new); applied += 1; print("OK    [%s]" % label)
    elif c == 0: print("SKIP  [%s] anchor NOT FOUND - untouched." % label); skipped += 1
    else: print("SKIP  [%s] anchor x%d - untouched." % (label, c)); skipped += 1
open(PATH, "w", encoding="utf-8").write(text)
DEAD = [
  ("POST /leads", "'/api/v2/vendor/leads', body"),
  ("PATCH /leads/:id", "/api/v2/vendor/leads/${leadId}" + chr(96) + ", body"),
  ("/leads/:id/detail", "/leads/${leadId}/detail"),
  ("/leads/:id/state", "/leads/${leadId}/state"),
  ("POST /clients", "'/api/v2/vendor/clients', body"),
  ("PATCH /clients/:id", "/api/v2/vendor/clients/${clientId}" + chr(96) + ", body"),
  ("DELETE /clients/:id", "deleteJson<{ ok: true; deleted: true } | ApiErr>(" + chr(96) + "/api/v2/vendor/clients/"),
  ("GET /clients/:v/:id", "/api/v2/vendor/clients/${vendorId}/${clientId}"),
  ("POST /expenses", "'/api/v2/vendor/expenses', body"),
  ("PATCH /expenses/:id", "/api/v2/vendor/expenses/${expenseId}" + chr(96) + ", body"),
  ("DELETE /expenses/:id", "deleteJson<{ ok: true; deleted: true } | ApiErr>(" + chr(96) + "/api/v2/vendor/expenses/"),
]
checks = [
  ("binderToLead has phone",       "name: b.client ?? null, phone: b.phone ?? null," in text),
  ("write helpers added",          "function currentVendorId()" in text and "type BinderWriteResponse" in text and "function foldNote" in text),
  ("createLead -> /binders",       "await postJson<BinderWriteResponse>(binderBase(v), {" in text and "stage: 'lead'," in text),
  ("createClient -> /binders",     "stage: 'client'," in text),
  ("createExpense -> /binders",    "direction: 'out', date: body.expense_date, note, stage: 'expense'," in text),
  ("edit endpoint used",           "/edit" + chr(96) in text),
  ("stage endpoint used",          "/stage" + chr(96) in text),
  ("hide endpoint used",           "/hide" + chr(96) in text),
  ("detail via ledger",            "const led = await fetchLedger(v);" in text and "find((x) => x.id === leadId)" in text),
  ("invoice money UNTOUCHED (4-C)","postJson<CreateInvoiceResponse | ApiErr>('/api/v2/vendor/invoices', body)" in text),
]
print(chr(10) + "-- dead typed write endpoints gone --")
deadok = True
for n,s in DEAD:
    g = s not in text
    print("  %s %s" % ("PASS" if g else "FAIL", n)); deadok = deadok and g
print(chr(10) + "-- behaviour checks --")
allok = deadok
for n,p in checks: print("  %s %s" % ("PASS" if p else "FAIL", n)); allok = allok and p
print(chr(10) + "(%d applied, %d skipped)" % (applied, skipped))
print("ALL CHECKS PASSED" if allok else "SOME CHECKS FAILED")
sys.exit(0 if allok else 2)
